using System.Text.RegularExpressions;
namespace LSE.AutoCADElectrical.ProjectTools;
public static class ProjectTransactionService{
 public static ProjectResult Execute(AppSettings s,ProjectTemplates t,ProjectRequest q,Action<string>? progress=null){
  Validate(t,q);string templateFolder=TemplateFolder(q);var log=new List<string>{$"Started: {DateTime.Now:s} by {Environment.UserName}@{Environment.MachineName}",$"Project: {q.ProjectName} ({q.JobNumber}) - {q.Title}",$"Customer: {q.Customer}   Product line: {(q.ProductLine.Length==0?"(none)":q.ProductLine)}{(q.LocationChoices.Count==0?"":" > "+string.Join(" > ",q.LocationChoices))}",$"Folder: {q.ProjectFolder}",$"Drawing template: {q.DrawingTemplatePath}",$"Template folder: {(templateFolder.Length==0?"(none)":templateFolder)}",$"Templates config: {t.Source}"};void Log(string m){log.Add(m);progress?.Invoke(m);}foreach(string m in log)progress?.Invoke(m);
  bool createdFolder=false;var created=new List<string>();
  try{
   if(!Directory.Exists(q.ProjectFolder)){Directory.CreateDirectory(q.ProjectFolder);createdFolder=true;Log("Project folder created: PASS");}
   else{if(File.Exists(q.WdpPath))throw new InvalidOperationException("A project file already exists: "+q.WdpPath);if(!q.AllowExistingFolder&&Directory.EnumerateFileSystemEntries(q.ProjectFolder).Any())throw new InvalidOperationException("The project folder already exists and is not empty: "+q.ProjectFolder+". Choose another folder name or tick 'Allow an existing, non-empty folder'.");Log("Using existing folder: PASS");}
   var wdp=new WdpDocument();int minLines=t.DescriptionLines.Count==0?8:t.DescriptionLines.Max(x=>x.Index);
   if(q.BaseProjectPath.Length>0){var b=WdpFileService.Parse(q.BaseProjectPath);foreach(var p in b.Properties)wdp.Properties[p.Key]=p.Value;foreach(var p in b.Options)wdp.Options[p.Key]=p.Value;wdp.Encoding=b.Encoding;if(b.Descriptions.Count>0)minLines=Math.Max(minLines,b.Descriptions.Keys.Max());Log($"LSE template project settings copied from {Path.GetFileName(q.BaseProjectPath)}: {b.Options.Count} option line(s) (+[n]: library paths, icon menus), {b.Properties.Count} property line(s) (?[n]), {b.Drawings.Count} template drawing(s) ignored, text encoding {WdpFileService.EncodingName(b.Encoding)}");}
   else Log("No LSE template project selected: AutoCAD Electrical applies its wd.env defaults when the project is opened. The E-CAD Doctor can add the LSE settings later.");
   foreach(var p in q.DescriptionLines)wdp.Descriptions[p.Key]=p.Value;
   var targets=q.Drawings.Select(r=>Path.Combine(q.ProjectFolder,EnsureDwg(r.FileName))).ToList();string? clash=targets.FirstOrDefault(File.Exists);if(clash is not null)throw new InvalidOperationException("A drawing with that name already exists: "+clash);
   string date=DateTime.Now.ToString(s.DateFormat);string wdmLib=FindWdmLibrary(s);Log(wdmLib.Length>0?"WD_M library block: "+wdmLib:"WD_M library block: not found (templates without WD_M will be reported)");int total=q.Drawings.Count;var paths=new List<string>();
   for(int i=0;i<total;i++){var r=q.Drawings[i];string file=targets[i];string template=RowTemplate(r,q,templateFolder);int sheet=SheetNumber(r.Sheet,i+1);
    var job=new DrawingJob{TemplatePath=template,OutputPath=file,Title=r.Description1,Subject=q.Title,FillTitleBlocks=q.FillTitleBlocks,SetWdmValues=q.SetWdmValues,WdmLibraryFile=wdmLib};
    foreach(var d in t.DescriptionLines)if(d.Attribute.Trim().Length>0&&q.DescriptionLines.TryGetValue(d.Index,out var v))job.TitleBlockValues[d.Attribute.Trim()]=v;
    Put(job.TitleBlockValues,t.TitleBlock.SheetAttribute,r.Sheet);Put(job.TitleBlockValues,t.TitleBlock.SheetMaxAttribute,total.ToString());Put(job.TitleBlockValues,t.TitleBlock.FileNameAttribute,Path.GetFileNameWithoutExtension(file));Put(job.TitleBlockValues,t.TitleBlock.DateAttribute,date);Put(job.TitleBlockValues,t.TitleBlock.SectionAttribute,r.Section);Put(job.TitleBlockValues,t.TitleBlock.SubsectionAttribute,r.Subsection);
    string[] desc={r.Description1,r.Description2,r.Description3};for(int k=0;k<t.TitleBlock.DescriptionAttributes.Count&&k<3;k++)Put(job.TitleBlockValues,t.TitleBlock.DescriptionAttributes[k],desc[k]);
    foreach(var f in t.TitleBlock.Fixed)job.TitleBlockValues[f.Key]=TemplateService.Expand(f.Value,q.JobNumber,sheet,q.ProjectName,DateTime.Now,s.DrawnBy,s.DateFormat,Tokens(q));
    Put(job.WdmValues,t.Wdm.SheetAttribute,r.Sheet);Put(job.WdmValues,t.Wdm.ProjectAttribute,q.IecProject);Put(job.WdmValues,t.Wdm.InstallationAttribute,q.IecInstallation);Put(job.WdmValues,t.Wdm.LocationAttribute,q.IecLocation);Put(job.WdmValues,t.Wdm.DrawingNumberAttribute,Path.GetFileNameWithoutExtension(file));
    var o=DrawingFactoryService.Create(job,t.TitleBlock,t.Wdm);created.Add(file);paths.Add(file);
    Log($"Drawing {i+1}/{total} {Path.GetFileName(file)} from {Path.GetFileName(template)}: title block {(o.TitleBlocksFound>0?$"{o.TitleBlocksFound} found, {o.TitleBlockAttributesSet} attribute(s) set":q.FillTitleBlocks?"NOT FOUND":"skipped")}; WD_M {(o.WdmFound?(o.WdmInserted?"inserted":"found")+$", {o.WdmAttributesSet} attribute(s) set":"MISSING - the template has no WD_M block and no wd_m.dwg library file was found")}");
    wdp.Drawings.Add(new WdpDrawing{Path=file,Section=r.Section.Trim(),Subsection=r.Subsection.Trim(),Folder=r.Folder.Trim(),Descriptions=new(){r.Description1.Trim(),r.Description2.Trim(),r.Description3.Trim()}});}
   WdpFileService.Write(q.WdpPath,wdp,minLines);created.Add(q.WdpPath);Log($"Project file written ({WdpFileService.EncodingName(wdp.Encoding)}, *[1..{minLines}], then +[n], then ?[n]): {q.WdpPath}");
   if(q.WriteWdlFile){string? p=q.CopyTemplateSidecars?WdpFileService.CopySidecar(q.WdpPath,q.BaseProjectPath,WdpFileService.LabelsPath):null;if(p is not null)Log("Description labels copied from the LSE template: "+p);else{p=WdpFileService.WriteLabels(q.WdpPath,t.DescriptionLines,t.LabelFile);Log("Description labels generated from the templates JSON: "+p);}created.Add(p);}
   if(q.WriteWdtFile){string? p=q.CopyTemplateSidecars?WdpFileService.CopySidecar(q.WdpPath,q.BaseProjectPath,WdpFileService.MappingPath):null;if(p is not null)Log("Title block mapping copied from the LSE template: "+p);else{p=WdpFileService.WriteMapping(q.WdpPath,t,wdp.Encoding);if(p is null)Log("Title block mapping (.wdt) skipped: no title block names are configured in the templates JSON.");else Log("Title block mapping generated from the templates JSON: "+p);}if(p is not null)created.Add(p);}
   if(q.WriteAepxFile){string p=WdpFileService.WriteConfiguration(q.WdpPath,paths);created.Add(p);Log("Project configuration written: "+p);}
   Log("Status: SUCCESS");File.WriteAllLines(Path.Combine(q.ProjectFolder,"LSE_ProjectReport.txt"),log);
   s.RecentProjects.RemoveAll(x=>x.Equals(q.WdpPath,StringComparison.OrdinalIgnoreCase));s.RecentProjects.Insert(0,q.WdpPath);if(s.RecentProjects.Count>25)s.RecentProjects.RemoveRange(25,s.RecentProjects.Count-25);SettingsService.Save(s);
   return new ProjectResult{Request=q,WdpPath=q.WdpPath,DrawingPaths=paths,Report=string.Join(Environment.NewLine,log)};}
  catch(Exception ex){Log("ERROR: "+ex.Message);foreach(string f in created)try{if(File.Exists(f)){File.Delete(f);Log("Rollback removed "+f);}}catch(Exception rx){Log("Rollback could not remove "+f+": "+rx.Message);}
   if(createdFolder)try{if(!Directory.EnumerateFileSystemEntries(q.ProjectFolder).Any()){Directory.Delete(q.ProjectFolder);Log("Rollback removed folder "+q.ProjectFolder);}}catch(Exception rx){Log("Rollback could not remove folder: "+rx.Message);}
   try{Directory.CreateDirectory(SettingsService.LogFolder);File.WriteAllLines(Path.Combine(SettingsService.LogFolder,$"ProjectReport_{DateTime.Now:yyyyMMdd_HHmmss}.txt"),log.Append("Detail: "+ex));}catch{}
   throw new InvalidOperationException(string.Join(Environment.NewLine,log),ex);}
 }
 public static void Validate(ProjectRequest q)=>Validate(new ProjectTemplates(),q);
 public static void Validate(ProjectTemplates t,ProjectRequest q){
  if(!TemplateService.JobNumberOk(t.Job,q.JobNumber))throw new InvalidOperationException((t.Job.NumberHint.Trim().Length>0?t.Job.NumberHint.Trim():"Job number is required")+(t.Job.NumberExample.Trim().Length>0?". Example: "+t.Job.NumberExample.Trim():"")+". Entered: '"+q.JobNumber+"'.");if(q.Title.Trim().Length==0)throw new InvalidOperationException("Project name (description line 1) is required.");
  foreach(var d in t.DescriptionLines.Where(x=>x.Required))if(!q.DescriptionLines.TryGetValue(d.Index,out var v)||v.Trim().Length==0)throw new InvalidOperationException("Description line "+d.Index+" ("+d.Label+") is required.");
  if(q.ProjectName.Trim().Length==0||q.ProjectName.IndexOfAny(Path.GetInvalidFileNameChars())>=0)throw new InvalidOperationException("Project name must be a valid file name (it becomes <name>.wdp).");if(q.ProjectFolder.Trim().Length==0||!Path.IsPathRooted(q.ProjectFolder))throw new InvalidOperationException("Project folder must be a full path.");
  if(!File.Exists(q.DrawingTemplatePath))throw new FileNotFoundException("Drawing template (.dwg/.dwt) was not found.",q.DrawingTemplatePath);if(q.BaseProjectPath.Length>0&&!File.Exists(q.BaseProjectPath))throw new FileNotFoundException("LSE template project (.wdp) was not found.",q.BaseProjectPath);
  if(q.Drawings.Count==0)throw new InvalidOperationException("Add at least one drawing.");var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);string templateFolder=TemplateFolder(q);
  foreach(var r in q.Drawings){string n=r.FileName.Trim();if(n.Length==0||n.IndexOfAny(Path.GetInvalidFileNameChars())>=0||n.Contains(Path.DirectorySeparatorChar)||n.Contains(Path.AltDirectorySeparatorChar))throw new InvalidOperationException("Every drawing needs a valid file name (no folders). Offending row: sheet '"+r.Sheet+"'.");if(!seen.Add(EnsureDwg(n)))throw new InvalidOperationException("Duplicate drawing file name: "+n);if(r.Sheet.Trim().Length==0)throw new InvalidOperationException("Every drawing needs a sheet value ("+n+").");string tp=RowTemplate(r,q,templateFolder);if(r.Template.Trim().Length>0&&!File.Exists(tp))throw new FileNotFoundException("Per-drawing template was not found: "+tp+" (row "+n+").",tp);}
 }
 public static string TemplateFolder(ProjectRequest q)=>SettingsService.TemplateFolder(q.BaseProjectPath,q.DrawingTemplatePath);
 public static string RowTemplate(DrawingRow r,ProjectRequest q,string templateFolder){string t=TemplateService.ResolveTemplate(r.Template,templateFolder);return t.Length>0?t:q.DrawingTemplatePath;}
 public static Dictionary<string,string> Tokens(ProjectRequest q)=>new(StringComparer.OrdinalIgnoreCase){["CUSTOMER"]=TemplateService.SafeName(q.Customer),["QUOTE"]=TemplateService.SafeName(q.Quote),["PRODUCTLINE"]=TemplateService.SafeName(q.ProductLine)};
 public static string EnsureDwg(string name){name=name.Trim();return name.EndsWith(".dwg",StringComparison.OrdinalIgnoreCase)?name:name+".dwg";}
 public static int SheetNumber(string sheet,int fallback){var m=Regex.Match(sheet,@"\d+");return m.Success&&int.TryParse(m.Value,out int n)?n:fallback;}
 static void Put(Dictionary<string,string> d,string key,string value){if(key.Trim().Length>0)d[key.Trim()]=value??"";}
 public static string FindWdmLibrary(AppSettings s){if(s.SymbolLibraryFolder.Length>0){string p=Path.Combine(s.SymbolLibraryFolder,"wd_m.dwg");if(File.Exists(p))return p;}string libs=Path.Combine(SettingsService.AeData(),"en-US","Libs");if(!Directory.Exists(libs))return "";try{return Directory.EnumerateFiles(libs,"wd_m.dwg",SearchOption.AllDirectories).FirstOrDefault()??"";}catch{return "";}}
}
